// What it does is obvious from the name
double calculateTotalBonus(const vector<Employee>& employees, int minimumYearsOfService) {
    double totalBonus = 0.0;
    const double BONUS_PERCENTAGE = 0.10;

    for (const auto& employee : employees) {
        if (employee.yearsOfService >= minimumYearsOfService) {
            totalBonus += employee.annualSalary * BONUS_PERCENTAGE;
        }
    }

    return totalBonus;
}

// Even better with algorithms
double calculateTotalBonusModern(const vector<Employee>& employees, int minimumYearsOfService) {
    const double BONUS_PERCENTAGE = 0.10;

    return transform_reduce(
        employees.begin(), employees.end(),
        0.0,
        plus<>(),
        [minimumYearsOfService, BONUS_PERCENTAGE](const Employee& e) {
            return (e.yearsOfService >= minimumYearsOfService) 
                   ? e.annualSalary * BONUS_PERCENTAGE 
                   : 0.0;
        }
    );
}

